params.command:
$ErrorActionPreference='Stop'
$repo=Join-Path $env:USERPROFILE 'local-ai-workspaces\mhw-mods'
$b='fix/codex-quota-dispatch-circuit-20260929'
$expected='40d4454fd6f5eabda9650acb58246025daff5ecc'
git -C $repo fetch origin --prune
$line=(git -C $repo ls-remote origin ("refs/heads/"+$b))
if(-not $line){ [pscustomobject]@{branch=$b;state='already-absent'}|ConvertTo-Json -Compress; exit 0 }
$actual=($line -split '\s+')[0]
if($actual -ne $expected){ throw "tip changed: $actual" }
$paths=@('tools/agent-control/README.md','tools/agent-control/lib/control-core.mjs','tools/agent-control/package.json','tools/agent-control/server.mjs','tools/agent-control/test/control-core.test.mjs')
foreach($p in $paths){
  $a=(git -C $repo rev-parse ("origin/main:"+$p)).Trim()
  $c=(git -C $repo rev-parse ("origin/"+$b+":"+$p)).Trim()
  if($a -ne $c){ throw "main no longer matches merged branch at $p" }
}
git -C $repo push origin --delete $b
if($LASTEXITCODE -ne 0){ throw "remote delete failed" }
git -C $repo fetch origin --prune
[pscustomobject]@{branch=$b;deleted=$true;proof='all 5 changed blobs identical on origin/main';main=(git -C $repo rev-parse origin/main).Trim()}|ConvertTo-Json -Compress
